import React, { useState } from 'react';
import Sidebar from './Sidebar';
import { useAuth } from '../App';

export default function DashboardLayout({ children, title, subtitle }) {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [notifOpen, setNotifOpen] = useState(false);
  const { user } = useAuth();

  const alerts = [
    { icon: '⚠️', text: 'Heavy rain expected Thursday', time: '2h ago', color: 'text-yellow-400' },
    { icon: '🔬', text: 'Rust risk detected in your zone', time: '5h ago', color: 'text-red-400' },
    { icon: '💰', text: 'Wheat MSP increased to ₹2,275', time: '1d ago', color: 'text-green-400' },
  ];

  return (
    <div className="min-h-screen bg-mesh flex">
      <Sidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />
      <div className="flex-1 lg:ml-64 flex flex-col min-h-screen">
        <header className="sticky top-0 z-20 glass-dark border-b border-green-900/30 px-6 py-3.5 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <button onClick={() => setSidebarOpen(true)} className="lg:hidden text-gray-400 hover:text-white text-2xl">☰</button>
            <div>
              <h1 className="font-display font-bold text-white text-lg">{title}</h1>
              {subtitle && <p className="text-gray-500 text-xs mt-0.5">{subtitle}</p>}
            </div>
          </div>
          <div className="flex items-center gap-3">
            {user?.gps && (
              <div className="hidden sm:flex items-center gap-1.5 glass-green px-3 py-1.5 rounded-full border border-green-700/30">
                <span className="text-xs">📍</span>
                <span className="text-green-300 text-xs">{user.gps.lat}, {user.gps.lng}</span>
              </div>
            )}
            <div className="relative">
              <button onClick={() => setNotifOpen(n => !n)}
                className="w-9 h-9 glass rounded-xl flex items-center justify-center text-gray-400 hover:text-white transition-all relative">
                🔔
                <span className="absolute -top-1 -right-1 w-4 h-4 bg-red-500 rounded-full text-white text-xs flex items-center justify-center">3</span>
              </button>
              {notifOpen && (
                <div className="absolute right-0 top-12 w-72 glass-dark rounded-2xl border border-green-900/30 shadow-2xl z-50 overflow-hidden">
                  <div className="p-3 border-b border-green-900/30 text-white text-sm font-semibold">Alerts</div>
                  {alerts.map((a, i) => (
                    <div key={i} className="p-3 hover:bg-white/5 transition-all flex items-start gap-3 border-b border-green-900/20">
                      <span>{a.icon}</span>
                      <div className="flex-1">
                        <div className={`text-xs font-medium ${a.color}`}>{a.text}</div>
                        <div className="text-gray-600 text-xs">{a.time}</div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
            <div className="flex items-center gap-1.5">
              <div className="w-2 h-2 rounded-full bg-green-400 animate-pulse" />
              <span className="text-green-400 text-xs font-medium hidden sm:block">AI Active</span>
            </div>
          </div>
        </header>
        <main className="flex-1 p-5 overflow-auto" onClick={() => setNotifOpen(false)}>
          {children}
        </main>
      </div>
    </div>
  );
}
